{
  "source": "def investigate(context, acquire):
    rows = context.get('rows', [])
    event_values = {}
    for row in rows:
        eid = row['event_id']
        val = row['value']
        if eid not in event_values:
            event_values[eid] = set()
        event_values[eid].add(val)
    total_sum = 0
    unresolved = False
    for eid, vals in event_values.items():
        if len(vals) > 1:
            unresolved = True
            break
        else:
            v = list(vals)[0]
            total_sum += v
    if unresolved:
        return {"value": None, "unresolved": True}
    else:
        return {"value": total_sum, "unresolved": False}",
  "scope": "Sums unique values per event ID from provided rows; detects conflicts.",
  "lesson": "Use a dictionary of sets to track distinct values per event ID. If any event has more than one distinct value, mark as unresolved."
}

